namespace ForensicEdu.Mobile.Core.Models;
public sealed record Account {public string Id{get;init;}="";public string FullName{get;init;}="";public string Nombres{get;init;}="";public string Apellidos{get;init;}="";public string Email{get;init;}="";public string Dni{get;init;}="";public string Phone{get;init;}="";public int Role{get;init;}public int Status{get;init;}public DateTimeOffset? ValidUntil{get;init;}public bool HasApprovedPurchase{get;init;}public string Name=>string.IsNullOrWhiteSpace(FullName)?$"{Nombres} {Apellidos}":FullName;public string Validity=>ValidUntil is null?"Acceso institucional":$"{Math.Max(0,(int)Math.Ceiling((ValidUntil.Value-DateTimeOffset.UtcNow).TotalDays))} días de acceso vigente";}
public sealed record LoginResult(string Token);
public sealed record RegisterInput(string Nombres,string Apellidos,string Email,string Password,string Dni,string Phone,string PaisResidencia,string NivelEducativo,string InstitucionEducativa,string Profesion,bool AcceptTerms,bool AcceptPrivacy){public string FullName=>$"{Nombres} {Apellidos}";public string TipoDocumento=>"DNI";}
